import{initBurgerMenu}from"./components/burgerMenu.js";import{renderPrograms}from"./components/programs.js";import{renderOverview}from"./components/overview.js";import{renderAchievementCards,renderAdaptiveInput}from"./components/example.js";import{renderMap}from"./components/address.js";import{renderFooter}from"./components/footer.js";import{logo}from"./svg/logo.js";import{logoIcon}from"./svg/logoIcon.js";const primaryColor="black";initBurgerMenu(),renderPrograms("black"),renderOverview(),renderAchievementCards(),renderAdaptiveInput(),renderMap(),renderFooter();const header=document.querySelector(".header"),headerLink=document.querySelectorAll(".nav__link"),headerLogo=document.getElementById("header-logo");headerLogo.innerHTML=`<span style="margin-right: 15px">${logoIcon()}</span>\n        <span style="margin-top: 5px">${logo()}</span>`,window.addEventListener("scroll",()=>{window.scrollY>150?(header.classList.add("scrolled"),headerLink.forEach(e=>e.classList.add("scrolled"))):(header.classList.remove("scrolled"),headerLink.forEach(e=>e.classList.remove("scrolled")))}),window.addEventListener("resize",()=>{renderAdaptiveInput()});